{"kind":"table","sheet":"Synthèse","address":"A1:H35","rows":35,"cols":8,"values":[[null,null,null,null,null,null,null,null],["SILENT HILL: HALO OF FLESH",null,null,null,null,null,null,null],["Références de combat et d’animation — Intégration des fiches dans le moteur — 17 octobre 2026\nAu 19 novembre 2026 : 204 portraits / 230 ; 135 vues latérales candidates.\n6 clips animés ; 32 décors bitmap actifs / 123 ; 136 portraits et combats distincts.\nRestants : 26 portraits absents ; 37 vues de combat absentes ; 58 vues héritées à revoir.",null,null,null,null,null,null,null],[null,null,null,null,null,null,null,null],["Périmètre","Nombre",null,"Œuvre (code)","Profils","Arènes","Mouvements","Constats"],["Profils de combattants",230,null,"sh1",20,9,400,41],["Arènes",123,null,"sh2",18,12,360,39],["Mouvements actuels à réviser",4600,null,"sh3",20,12,400,50],["Dont supers / désespoir",460,null,"sh4",32,10,640,53],["Finishers de personnages",460,null,"origins",11,6,220,22],["Finishers d’arènes",123,null,"homecoming",17,11,340,37],["Séquences de présentation",1610,null,"shattered",5,5,100,3],["Clips de base à préparer",2300,null,"downpour",14,7,280,21],["Pistes d’arène inventoriées",1799,null,"arcade",19,12,380,20],["Gestes / constats référencés",435,null,"bom",28,8,560,31],["Sources consultées",277,null,"pt",1,1,20,3],["Profils avec PNG candidats",204,null,"shortmessage",1,3,20,1],["Montages animés candidats",6,null,"shf",19,9,380,78],["Profils validés en fidélité 1:1",0,null,"film",13,8,260,17],["Actions encore ouvertes",840,null,"ascension",7,3,140,8],["Priorités P0 encore ouvertes",93,null,"townfall",5,7,100,11],[null,null,null,null,null,null,null,null],["Lecture et règles de production",null,null,null,null,null,null,null],[null,null,null,null,null,null,null,null],["Les descriptions documentées se trouvent dans Gestes référencés. Les propositions de versus sont indiquées séparément.",null,null,null,null,null,null,null],["Une source sur un monstre ne certifie ni ses 20 mouvements actuels, ni ses timings, ni ses poses de combat.",null,null,null,null,null,null,null],["Supers, finishers, poses de manche et sorties sont des adaptations à produire, même lorsque leur inspiration est documentée.",null,null,null,null,null,null,null],["Les poses de première manche restent réversibles. Les finishers attendent une victoire définitive du match.",null,null,null,null,null,null,null],["Les cases jaunes de statut, de responsable et de relevé vidéo sont modifiables. Les filtres permettent le suivi par œuvre.",null,null,null,null,null,null,null],["Les durées et FPS des sources restent vides tant qu’aucune capture image par image ne les a établis.",null,null,null,null,null,null,null],["Les nombres de préparation, dégâts et portée proviennent du moteur actuel. Ils ne sont pas des valeurs officielles Silent Hill.",null,null,null,null,null,null,null],["230 fiches appliquées ; 205 montages de finisher ; 163 éléments d’arène ; 9 hooks. 1101 commandes bloquées. Images : 204 profils avec PNG candidats, 6 montage animé candidat, 0 fidélité 1:1 certifiée.",null,null,null,null,null,null,null],["Format prévu : un PNG transparent indépendant par image, silhouette entière, accessoires et appuis contrôlés.",null,null,null,null,null,null,null],["Les rôles non combattants, obstacles et variantes incertaines restent visibles pour être décidés, sans leur inventer de canon.",null,null,null,null,null,null,null],["Base de comparaison : PR #4, commit d11cf4e8c03668aa535631cb2ef60767ee51e75b.",null,null,null,null,null,null,null]]}
